#!/usr/bin/env python3
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parent
SRC = ROOT / "v172-source/app/src/main/java/com/sentongoharuna/pulse"
GRADLE = ROOT / "v172-source/app/build.gradle.kts"

required = [
    SRC / "DevelopUgandaColorEngine.kt",
    SRC / "DevelopUgandaColorTuner.kt",
    SRC / "DevelopUgandaLiveGradePanel.kt",
    SRC / "DevelopUgandaCameraActivity.kt",
    SRC / "DevelopUgandaLiveActivity.kt",
    GRADLE,
]
for path in required:
    if not path.exists():
        raise SystemExit(f"V235 required base file missing: {path}")

EVERYDAY = 'package com.sentongoharuna.pulse\n\nimport android.content.Context\nimport org.json.JSONArray\nimport org.json.JSONObject\nimport java.util.Locale\nimport kotlin.math.abs\nimport kotlin.math.max\n\n/**\n * V235 Everyday Color Mixer.\n *\n * These six plain-language controls sit after the authored Uganda Scene LUT.\n * 100% preserves the LUT, 0% gently removes that color family, and 200%\n * increases it. Values are saved independently per LUT and camera scope.\n */\nobject DevelopUgandaEverydayColorMixer {\n\n    data class Family(\n        val name: String,\n        val hex: String,\n        val example: String\n    )\n\n    data class Tuning(\n        val values: IntArray\n    ) {\n        fun value(index: Int): Int =\n            values.getOrNull(index)?.coerceIn(0, 200) ?: 100\n\n        fun isDefault(): Boolean =\n            values.all { it == 100 }\n    }\n\n    private const val PREFS = "develop_uganda_v235_everyday_color_mixer"\n    private const val DEFAULT = 100\n\n    val families = listOf(\n        Family("GREEN", "#3EA65A", "salad • leaves • vegetation"),\n        Family("RED", "#D93D35", "meat • signs • clothes"),\n        Family("YELLOW", "#F2C84B", "banana • sun • warm lights"),\n        Family("BLUE", "#3F83D5", "sky • water • cool glass"),\n        Family("ORANGE", "#E97D32", "food • brick • warm light"),\n        Family("BROWN", "#7B5736", "earth • wood • coffee")\n    )\n\n    fun load(\n        context: Context,\n        scope: String,\n        profileId: String\n    ): Tuning {\n        val prefs = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)\n        return Tuning(\n            IntArray(families.size) { index ->\n                prefs.getInt(key(scope, profileId, index), DEFAULT)\n                    .coerceIn(0, 200)\n            }\n        )\n    }\n\n    fun neutral(): Tuning =\n        Tuning(IntArray(families.size) { DEFAULT })\n\n    fun set(\n        context: Context,\n        scope: String,\n        profileId: String,\n        index: Int,\n        value: Int\n    ) {\n        context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)\n            .edit()\n            .putInt(\n                key(scope, profileId, index),\n                value.coerceIn(0, 200)\n            )\n            .apply()\n    }\n\n    fun reset(\n        context: Context,\n        scope: String,\n        profileId: String\n    ) {\n        val editor =\n            context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)\n                .edit()\n\n        families.indices.forEach { index ->\n            editor.remove(key(scope, profileId, index))\n        }\n\n        editor.apply()\n    }\n\n    fun tuningJson(\n        context: Context,\n        scope: String,\n        profileId: String\n    ): JSONArray {\n        val tuning = load(context, scope, profileId)\n        return JSONArray().apply {\n            families.forEachIndexed { index, family ->\n                put(\n                    JSONObject()\n                        .put("name", family.name)\n                        .put("hex", family.hex)\n                        .put("example", family.example)\n                        .put("amount_percent", tuning.value(index))\n                )\n            }\n        }\n    }\n\n    /**\n     * Small matrix approximation used only by the live operator monitor.\n     * The final COLOR_MASTER uses apply() inside the real 17^3 LUT.\n     */\n    fun previewBias(tuning: Tuning): FloatArray {\n        var rBias = 0f\n        var gBias = 0f\n        var bBias = 0f\n\n        families.forEachIndexed { index, family ->\n            val delta = (tuning.value(index) - DEFAULT) / 100f\n            if (abs(delta) < 0.001f) return@forEachIndexed\n\n            val rgb = rgb(family.hex)\n            val neutral =\n                rgb[0] * 0.2126f +\n                    rgb[1] * 0.7152f +\n                    rgb[2] * 0.0722f\n\n            rBias += (rgb[0] - neutral) * delta * 0.055f\n            gBias += (rgb[1] - neutral) * delta * 0.055f\n            bBias += (rgb[2] - neutral) * delta * 0.055f\n        }\n\n        return floatArrayOf(\n            rBias.coerceIn(-0.10f, 0.10f),\n            gBias.coerceIn(-0.10f, 0.10f),\n            bBias.coerceIn(-0.10f, 0.10f)\n        )\n    }\n\n    /**\n     * Hue-family adjustment for the final 17^3 LUT.\n     *\n     * This deliberately uses broad, overlapping masks rather than razor-sharp\n     * hue keys, which helps phone footage avoid banding and unnatural edges.\n     */\n    fun apply(\n        inputR: Float,\n        inputG: Float,\n        inputB: Float,\n        tuning: Tuning\n    ): FloatArray {\n        var r = inputR.coerceIn(0f, 1f)\n        var g = inputG.coerceIn(0f, 1f)\n        var b = inputB.coerceIn(0f, 1f)\n\n        val maxC = max(r, max(g, b))\n        val minC = minOf(r, g, b)\n        val chroma = (maxC - minC).coerceIn(0f, 1f)\n        val luma =\n            (r * 0.2126f + g * 0.7152f + b * 0.0722f)\n                .coerceIn(0f, 1f)\n        val mid =\n            (1f - abs(luma * 2f - 1f))\n                .coerceIn(0f, 1f)\n\n        val greenMask =\n            ((g - max(r, b)) * 2.7f)\n                .coerceIn(0f, 1f) *\n                (0.35f + chroma * 0.65f)\n\n        val redMask =\n            ((r - max(g, b)) * 2.5f)\n                .coerceIn(0f, 1f) *\n                (0.35f + chroma * 0.65f)\n\n        val yellowMask =\n            ((minOf(r, g) - b) * 2.3f)\n                .coerceIn(0f, 1f) *\n                (0.30f + chroma * 0.70f) *\n                (0.55f + luma * 0.45f)\n\n        val blueMask =\n            ((b - max(r, g)) * 2.5f)\n                .coerceIn(0f, 1f) *\n                (0.35f + chroma * 0.65f)\n\n        val warmMask =\n            ((r - b) * 1.85f)\n                .coerceIn(0f, 1f)\n\n        val orangeMask =\n            warmMask *\n                ((g - b) * 2.0f).coerceIn(0f, 1f) *\n                (0.38f + chroma * 0.62f) *\n                (0.45f + mid * 0.55f)\n\n        val brownMask =\n            warmMask *\n                (1f - luma).coerceIn(0f, 1f) *\n                (0.35f + mid * 0.65f) *\n                (0.30f + chroma * 0.70f)\n\n        val masks = floatArrayOf(\n            greenMask,\n            redMask,\n            yellowMask,\n            blueMask,\n            orangeMask,\n            brownMask\n        )\n\n        families.forEachIndexed { index, family ->\n            val delta = (tuning.value(index) - DEFAULT) / 100f\n            val mask = masks[index].coerceIn(0f, 1f)\n            if (abs(delta) < 0.001f || mask < 0.001f) {\n                return@forEachIndexed\n            }\n\n            val target = rgb(family.hex)\n\n            if (delta > 0f) {\n                val weight = (mask * delta * 0.24f).coerceIn(0f, 0.28f)\n                r = mix(r, target[0], weight)\n                g = mix(g, target[1], weight)\n                b = mix(b, target[2], weight)\n            } else {\n                val neutral =\n                    (r * 0.2126f + g * 0.7152f + b * 0.0722f)\n                        .coerceIn(0f, 1f)\n                val weight =\n                    (mask * -delta * 0.58f)\n                        .coerceIn(0f, 0.62f)\n\n                r = mix(r, neutral, weight)\n                g = mix(g, neutral, weight)\n                b = mix(b, neutral, weight)\n            }\n        }\n\n        return floatArrayOf(\n            r.coerceIn(0f, 1f),\n            g.coerceIn(0f, 1f),\n            b.coerceIn(0f, 1f)\n        )\n    }\n\n    private fun rgb(hex: String): FloatArray {\n        val clean = hex.removePrefix("#")\n        val value = clean.toLong(16)\n        return floatArrayOf(\n            ((value shr 16) and 0xFF) / 255f,\n            ((value shr 8) and 0xFF) / 255f,\n            (value and 0xFF) / 255f\n        )\n    }\n\n    private fun mix(a: Float, b: Float, t: Float): Float =\n        (a + (b - a) * t).coerceIn(0f, 1f)\n\n    private fun key(\n        scope: String,\n        profileId: String,\n        index: Int\n    ): String =\n        "${safe(scope)}_${safe(profileId)}_$index"\n\n    private fun safe(value: String): String =\n        value.uppercase(Locale.US)\n            .replace(Regex("[^A-Z0-9_]+"), "_")\n            .take(48)\n            .ifBlank { "GLOBAL" }\n}\n'
NAVY_SHEET = 'package com.sentongoharuna.pulse\n\nimport android.app.Dialog\nimport android.graphics.Color\nimport android.graphics.Typeface\nimport android.graphics.drawable.ColorDrawable\nimport android.graphics.drawable.GradientDrawable\nimport android.view.Gravity\nimport android.view.ViewGroup\nimport android.view.WindowManager\nimport android.widget.Button\nimport android.widget.LinearLayout\nimport android.widget.ScrollView\nimport android.widget.TextView\nimport androidx.appcompat.app.AppCompatActivity\n\n/**\n * V235 keeps the V234 navy-safe design language:\n * dark navy, thin accent borders, bottom-sheet placement and a scroll-safe list.\n */\nobject DevelopUgandaNavySheet {\n\n    fun show(\n        activity: AppCompatActivity,\n        title: String,\n        subtitle: String,\n        labels: Array<String>,\n        selectedIndex: Int,\n        onSelected: (Int) -> Unit\n    ) {\n        val dialog = Dialog(activity)\n        dialog.setCancelable(true)\n\n        val panel = LinearLayout(activity).apply {\n            orientation = LinearLayout.VERTICAL\n            setPadding(dp(activity, 14), dp(activity, 12), dp(activity, 14), dp(activity, 14))\n            background = rounded(\n                activity,\n                0xF7031829.toInt(),\n                0xFF456983.toInt(),\n                22\n            )\n        }\n\n        val header = LinearLayout(activity).apply {\n            orientation = LinearLayout.HORIZONTAL\n            gravity = Gravity.CENTER_VERTICAL\n        }\n\n        val titleBox = LinearLayout(activity).apply {\n            orientation = LinearLayout.VERTICAL\n        }\n\n        titleBox.addView(\n            TextView(activity).apply {\n                text = title\n                textSize = 14.5f\n                setTextColor(Color.WHITE)\n                typeface = Typeface.DEFAULT_BOLD\n            }\n        )\n\n        titleBox.addView(\n            TextView(activity).apply {\n                text = subtitle\n                textSize = 7.7f\n                setTextColor(0xFF91B6A0.toInt())\n                typeface = Typeface.DEFAULT_BOLD\n                setPadding(0, dp(activity, 2), 0, dp(activity, 5))\n            }\n        )\n\n        header.addView(\n            titleBox,\n            LinearLayout.LayoutParams(\n                0,\n                ViewGroup.LayoutParams.WRAP_CONTENT,\n                1f\n            )\n        )\n\n        header.addView(\n            Button(activity).apply {\n                text = "×"\n                textSize = 18f\n                isAllCaps = false\n                setTextColor(Color.WHITE)\n                background = rounded(\n                    activity,\n                    0xFF092236.toInt(),\n                    0xFF73B7D9.toInt(),\n                    13\n                )\n                setOnClickListener { dialog.dismiss() }\n            },\n            LinearLayout.LayoutParams(\n                dp(activity, 44),\n                dp(activity, 40)\n            )\n        )\n\n        panel.addView(header)\n\n        val list = LinearLayout(activity).apply {\n            orientation = LinearLayout.VERTICAL\n        }\n\n        labels.forEachIndexed { index, label ->\n            val selected = index == selectedIndex\n\n            list.addView(\n                Button(activity).apply {\n                    text =\n                        if (selected) {\n                            "✓  $label"\n                        } else {\n                            label\n                        }\n                    textSize = 9.1f\n                    isAllCaps = false\n                    gravity = Gravity.START or Gravity.CENTER_VERTICAL\n                    typeface = Typeface.DEFAULT_BOLD\n                    setTextColor(Color.WHITE)\n                    setPadding(\n                        dp(activity, 13),\n                        0,\n                        dp(activity, 10),\n                        0\n                    )\n                    minHeight = dp(activity, 50)\n                    background = rounded(\n                        activity,\n                        if (selected) {\n                            0xFF1E3448.toInt()\n                        } else {\n                            0xFF092236.toInt()\n                        },\n                        if (selected) {\n                            0xFF91B6A0.toInt()\n                        } else {\n                            0xFF456983.toInt()\n                        },\n                        14\n                    )\n                    setOnClickListener {\n                        dialog.dismiss()\n                        onSelected(index)\n                    }\n                },\n                LinearLayout.LayoutParams(\n                    ViewGroup.LayoutParams.MATCH_PARENT,\n                    dp(activity, 50)\n                ).apply {\n                    topMargin = dp(activity, 5)\n                }\n            )\n        }\n\n        val scroll = ScrollView(activity).apply {\n            isFillViewport = false\n            addView(\n                list,\n                ViewGroup.LayoutParams(\n                    ViewGroup.LayoutParams.MATCH_PARENT,\n                    ViewGroup.LayoutParams.WRAP_CONTENT\n                )\n            )\n        }\n\n        panel.addView(\n            scroll,\n            LinearLayout.LayoutParams(\n                ViewGroup.LayoutParams.MATCH_PARENT,\n                0,\n                1f\n            )\n        )\n\n        dialog.setContentView(panel)\n\n        dialog.setOnShowListener {\n            dialog.window?.let { window ->\n                window.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))\n                window.setGravity(Gravity.BOTTOM)\n                window.setLayout(\n                    ViewGroup.LayoutParams.MATCH_PARENT,\n                    (activity.resources.displayMetrics.heightPixels * 0.72f).toInt()\n                )\n                window.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND)\n                val attributes = window.attributes\n                attributes.dimAmount = 0.44f\n                window.attributes = attributes\n            }\n        }\n\n        dialog.show()\n    }\n\n    private fun rounded(\n        activity: AppCompatActivity,\n        fill: Int,\n        stroke: Int,\n        radius: Int\n    ): GradientDrawable =\n        GradientDrawable().apply {\n            shape = GradientDrawable.RECTANGLE\n            setColor(fill)\n            cornerRadius = dp(activity, radius).toFloat()\n            setStroke(dp(activity, 1), stroke)\n        }\n\n    private fun dp(\n        activity: AppCompatActivity,\n        value: Int\n    ): Int =\n        (value * activity.resources.displayMetrics.density).toInt()\n}\n'
LIVE_GRADE = 'package com.sentongoharuna.pulse\n\nimport android.content.res.ColorStateList\nimport android.graphics.Color\nimport android.graphics.Typeface\nimport android.graphics.drawable.GradientDrawable\nimport android.os.Handler\nimport android.os.Looper\nimport android.view.Gravity\nimport android.view.MotionEvent\nimport android.view.View\nimport android.view.ViewGroup\nimport android.widget.Button\nimport android.widget.FrameLayout\nimport android.widget.LinearLayout\nimport android.widget.ScrollView\nimport android.widget.SeekBar\nimport android.widget.TextView\nimport androidx.appcompat.app.AppCompatActivity\nimport androidx.camera.view.PreviewView\n\n/**\n * V235 Uganda LUT Mixer Pro.\n *\n * Operator-only live grading:\n * - original CameraX MP4 remains untouched\n * - authored Uganda Scene palette controls remain 0–200%\n * - six plain-language colors are added to every LUT, also 0–200%\n * - HOLD ORIGINAL gives instant comparison\n * - final COLOR_MASTER uses the real tuned 17^3 Media3 LUT\n */\nobject DevelopUgandaLiveGradePanel {\n\n    private const val TAG = "develop_uganda_v235_live_grade_panel"\n\n    fun attach(\n        activity: AppCompatActivity,\n        root: FrameLayout,\n        previewView: PreviewView,\n        scopeProvider: () -> String,\n        hintProvider: () -> String\n    ) {\n        if (root.findViewWithTag<View>(TAG) != null) {\n            return\n        }\n\n        Controller(\n            activity,\n            root,\n            previewView,\n            scopeProvider,\n            hintProvider\n        ).attach()\n    }\n\n    private class Controller(\n        private val activity: AppCompatActivity,\n        private val root: FrameLayout,\n        private val previewView: PreviewView,\n        private val scopeProvider: () -> String,\n        private val hintProvider: () -> String\n    ) {\n        private val handler = Handler(Looper.getMainLooper())\n        private var bypass = false\n        private var expanded = false\n        private var loading = false\n        private var lastSignature = ""\n\n        private lateinit var chip: Button\n        private lateinit var card: LinearLayout\n        private lateinit var active: TextView\n        private lateinit var masterLabel: TextView\n        private lateinit var masterSeek: SeekBar\n        private lateinit var scenePaletteHost: LinearLayout\n        private lateinit var everydayHost: LinearLayout\n        private lateinit var lookButton: Button\n        private lateinit var compareButton: Button\n\n        private val refreshRunnable =\n            object : Runnable {\n                override fun run() {\n                    if (activity.isFinishing || activity.isDestroyed) {\n                        return\n                    }\n\n                    refreshIfNeeded()\n                    handler.postDelayed(this, 650L)\n                }\n            }\n\n        fun attach() {\n            previewView.implementationMode =\n                PreviewView.ImplementationMode.COMPATIBLE\n\n            DevelopUgandaColorEngine.setMonitorEnabled(\n                activity,\n                true\n            )\n\n            buildChip()\n            buildCard()\n            applyNow()\n            refreshUi(force = true)\n            handler.postDelayed(refreshRunnable, 650L)\n        }\n\n        private fun buildChip() {\n            chip = Button(activity).apply {\n                tag = TAG\n                text = "GRADE • V235\\nMIX ▸"\n                textSize = 8.2f\n                isAllCaps = false\n                typeface = Typeface.DEFAULT_BOLD\n                setTextColor(Color.WHITE)\n                background = rounded(\n                    0xE6031829.toInt(),\n                    0xFF73B7D9.toInt(),\n                    16\n                )\n                setOnClickListener {\n                    expanded = !expanded\n                    card.visibility =\n                        if (expanded) View.VISIBLE else View.GONE\n                    refreshUi(force = true)\n                }\n            }\n\n            root.addView(\n                chip,\n                FrameLayout.LayoutParams(\n                    dp(96),\n                    dp(50)\n                ).apply {\n                    gravity = Gravity.END or Gravity.CENTER_VERTICAL\n                    rightMargin = dp(8)\n                }\n            )\n        }\n\n        private fun buildCard() {\n            card = LinearLayout(activity).apply {\n                orientation = LinearLayout.VERTICAL\n                setPadding(dp(10), dp(9), dp(10), dp(9))\n                background = rounded(\n                    0xF7031829.toInt(),\n                    0xFF456983.toInt(),\n                    18\n                )\n                visibility = View.GONE\n                elevation = dp(10).toFloat()\n            }\n\n            val header = LinearLayout(activity).apply {\n                orientation = LinearLayout.HORIZONTAL\n                gravity = Gravity.CENTER_VERTICAL\n            }\n\n            active = label(\n                "V235 • UGANDA LUT MIXER",\n                9.5f,\n                Color.WHITE,\n                true\n            ).apply {\n                maxLines = 2\n            }\n\n            header.addView(\n                active,\n                LinearLayout.LayoutParams(\n                    0,\n                    ViewGroup.LayoutParams.WRAP_CONTENT,\n                    1f\n                )\n            )\n\n            val close = Button(activity).apply {\n                text = "×"\n                textSize = 18f\n                isAllCaps = false\n                setTextColor(Color.WHITE)\n                background = rounded(\n                    0xFF092236.toInt(),\n                    0xFF73B7D9.toInt(),\n                    12\n                )\n                setOnClickListener {\n                    expanded = false\n                    card.visibility = View.GONE\n                }\n            }\n\n            header.addView(\n                close,\n                LinearLayout.LayoutParams(\n                    dp(42),\n                    dp(38)\n                )\n            )\n\n            card.addView(header)\n\n            val quick = LinearLayout(activity).apply {\n                orientation = LinearLayout.HORIZONTAL\n                setPadding(0, dp(5), 0, dp(4))\n            }\n\n            lookButton =\n                smallButton("LOOK ▾", 0xFF73B7D9.toInt()).apply {\n                    setOnClickListener { chooseLook() }\n                }\n\n            compareButton =\n                smallButton(\n                    "HOLD ORIGINAL",\n                    0xFFD0B06F.toInt()\n                ).apply {\n                    setOnTouchListener { _, event ->\n                        when (event.actionMasked) {\n                            MotionEvent.ACTION_DOWN -> {\n                                bypass = true\n                                DevelopUgandaColorEngine.clearPreviewMonitor(\n                                    previewView\n                                )\n                                text = "ORIGINAL • HOLD"\n                                true\n                            }\n\n                            MotionEvent.ACTION_UP,\n                            MotionEvent.ACTION_CANCEL -> {\n                                bypass = false\n                                text = "HOLD ORIGINAL"\n                                applyNow()\n                                true\n                            }\n\n                            else -> true\n                        }\n                    }\n                }\n\n            val reset =\n                smallButton("RESET ALL", 0xFF91B6A0.toInt()).apply {\n                    setOnClickListener { resetCurrent() }\n                }\n\n            quick.addView(lookButton, weight())\n            quick.addView(space(dp(5)), fixed(dp(5), 1))\n            quick.addView(compareButton, weight())\n            quick.addView(space(dp(5)), fixed(dp(5), 1))\n            quick.addView(reset, weight())\n\n            card.addView(quick)\n\n            masterLabel =\n                label(\n                    "MASTER LUT STRENGTH • 0%",\n                    8f,\n                    0xFFF1F3F8.toInt(),\n                    true\n                )\n\n            card.addView(masterLabel)\n\n            masterSeek = SeekBar(activity).apply {\n                max = 100\n                progressTintList =\n                    ColorStateList.valueOf(0xFF73B7D9.toInt())\n                thumbTintList =\n                    ColorStateList.valueOf(0xFF73B7D9.toInt())\n\n                setOnSeekBarChangeListener(\n                    object : SeekBar.OnSeekBarChangeListener {\n                        override fun onProgressChanged(\n                            seekBar: SeekBar?,\n                            progress: Int,\n                            fromUser: Boolean\n                        ) {\n                            masterLabel.text =\n                                "MASTER LUT STRENGTH • $progress%"\n\n                            if (fromUser && !loading) {\n                                DevelopUgandaColorEngine.setStrength(\n                                    activity,\n                                    scope(),\n                                    progress\n                                )\n                                applyNow()\n                                updateHeader()\n                            }\n                        }\n\n                        override fun onStartTrackingTouch(\n                            seekBar: SeekBar?\n                        ) { }\n\n                        override fun onStopTrackingTouch(\n                            seekBar: SeekBar?\n                        ) { }\n                    }\n                )\n            }\n\n            card.addView(masterSeek)\n\n            val scrollBody = LinearLayout(activity).apply {\n                orientation = LinearLayout.VERTICAL\n            }\n\n            scrollBody.addView(\n                sectionTitle(\n                    "SCENE PALETTE • AUTHORED LUT COLORS • 0–200%"\n                )\n            )\n\n            scenePaletteHost = LinearLayout(activity).apply {\n                orientation = LinearLayout.VERTICAL\n            }\n            scrollBody.addView(scenePaletteHost)\n\n            scrollBody.addView(\n                sectionTitle(\n                    "EVERYDAY COLORS • SAME 6 ON EVERY LUT • 0–200%"\n                ).apply {\n                    setPadding(0, dp(8), 0, dp(2))\n                }\n            )\n\n            scrollBody.addView(\n                label(\n                    "GREEN • RED • YELLOW • BLUE • ORANGE • BROWN\\n100% keeps the designed LUT. Move only the colors you want.",\n                    7.0f,\n                    0xFFAEB7C7.toInt(),\n                    false\n                ).apply {\n                    setPadding(0, 0, 0, dp(4))\n                }\n            )\n\n            everydayHost = LinearLayout(activity).apply {\n                orientation = LinearLayout.VERTICAL\n            }\n            scrollBody.addView(everydayHost)\n\n            scrollBody.addView(\n                label(\n                    "AUTO-SAVED PER LUT • ORIGINAL MP4 stays clean. COLOR_MASTER.mp4 receives the final V235 tuned 17³ LUT.",\n                    7.1f,\n                    0xFF91B6A0.toInt(),\n                    true\n                ).apply {\n                    setPadding(0, dp(7), 0, dp(4))\n                }\n            )\n\n            val scroll = ScrollView(activity).apply {\n                isFillViewport = false\n                addView(\n                    scrollBody,\n                    ViewGroup.LayoutParams(\n                        ViewGroup.LayoutParams.MATCH_PARENT,\n                        ViewGroup.LayoutParams.WRAP_CONTENT\n                    )\n                )\n            }\n\n            card.addView(\n                scroll,\n                LinearLayout.LayoutParams(\n                    ViewGroup.LayoutParams.MATCH_PARENT,\n                    0,\n                    1f\n                )\n            )\n\n            val displayHeight =\n                activity.resources.displayMetrics.heightPixels\n            val desiredHeight =\n                (displayHeight * 0.66f)\n                    .toInt()\n                    .coerceIn(\n                        dp(390),\n                        dp(640)\n                    )\n\n            root.addView(\n                card,\n                FrameLayout.LayoutParams(\n                    ViewGroup.LayoutParams.MATCH_PARENT,\n                    desiredHeight\n                ).apply {\n                    gravity = Gravity.BOTTOM\n                    leftMargin = dp(8)\n                    rightMargin = dp(8)\n                    bottomMargin = dp(76)\n                }\n            )\n        }\n\n        private fun chooseLook() {\n            val labels =\n                DevelopUgandaColorEngine.menuLabels()\n            val selected =\n                DevelopUgandaColorEngine.selectedMenuIndex(\n                    activity,\n                    scope()\n                )\n\n            DevelopUgandaNavySheet.show(\n                activity = activity,\n                title = "V235 • UGANDA COLOR LOOK",\n                subtitle =\n                    "SELECT LUT • NUMBER = LOOK VERSION • SCROLL-SAFE NAVY SHEET",\n                labels = labels,\n                selectedIndex = selected\n            ) { which ->\n                DevelopUgandaColorEngine.setSelectedMenuIndex(\n                    activity,\n                    scope(),\n                    which\n                )\n                lastSignature = ""\n                applyNow()\n                refreshUi(force = true)\n            }\n        }\n\n        private fun resetCurrent() {\n            val selection = resolve()\n            val profile = selection.profile ?: return\n\n            DevelopUgandaColorTuner.reset(\n                activity,\n                scope(),\n                profile.id\n            )\n\n            DevelopUgandaEverydayColorMixer.reset(\n                activity,\n                scope(),\n                profile.id\n            )\n\n            DevelopUgandaColorEngine.setStrength(\n                activity,\n                scope(),\n                profile.defaultStrength\n            )\n\n            lastSignature = ""\n            applyNow()\n            refreshUi(force = true)\n        }\n\n        private fun rebuildControls(\n            selection: DevelopUgandaColorEngine.ResolvedSelection\n        ) {\n            scenePaletteHost.removeAllViews()\n            everydayHost.removeAllViews()\n\n            val profile = selection.profile\n\n            if (profile == null) {\n                val raw =\n                    label(\n                        "ORIGINAL • LIVE GRADE BYPASSED",\n                        8f,\n                        0xFFAEB7C7.toInt(),\n                        true\n                    )\n\n                scenePaletteHost.addView(raw)\n                return\n            }\n\n            rebuildScenePalette(profile)\n            rebuildEverydayColors(profile)\n        }\n\n        private fun rebuildScenePalette(\n            profile: DevelopUgandaColorEngine.Profile\n        ) {\n            val style =\n                DevelopUgandaColorTuner.style(profile.id)\n                    ?: return\n\n            val tuning =\n                DevelopUgandaColorTuner.load(\n                    activity,\n                    scope(),\n                    profile.id\n                )\n\n            style.slots.forEachIndexed { index, slot ->\n                val row =\n                    mixerRow(\n                        number = index + 1,\n                        name = slot.name,\n                        example = slot.role.name.lowercase(),\n                        hex = slot.hex,\n                        value = tuning.value(index)\n                    ) { progress ->\n                        DevelopUgandaColorTuner.set(\n                            activity,\n                            scope(),\n                            profile.id,\n                            index,\n                            progress\n                        )\n                    }\n\n                scenePaletteHost.addView(row)\n            }\n        }\n\n        private fun rebuildEverydayColors(\n            profile: DevelopUgandaColorEngine.Profile\n        ) {\n            val tuning =\n                DevelopUgandaEverydayColorMixer.load(\n                    activity,\n                    scope(),\n                    profile.id\n                )\n\n            DevelopUgandaEverydayColorMixer.families\n                .forEachIndexed { index, family ->\n                    val row =\n                        mixerRow(\n                            number = index + 1,\n                            name = family.name,\n                            example = family.example,\n                            hex = family.hex,\n                            value = tuning.value(index)\n                        ) { progress ->\n                            DevelopUgandaEverydayColorMixer.set(\n                                activity,\n                                scope(),\n                                profile.id,\n                                index,\n                                progress\n                            )\n                        }\n\n                    everydayHost.addView(row)\n                }\n        }\n\n        private fun mixerRow(\n            number: Int,\n            name: String,\n            example: String,\n            hex: String,\n            value: Int,\n            save: (Int) -> Unit\n        ): LinearLayout {\n            val row = LinearLayout(activity).apply {\n                orientation = LinearLayout.HORIZONTAL\n                gravity = Gravity.CENTER_VERTICAL\n                setPadding(0, dp(1), 0, dp(1))\n            }\n\n            val swatch = TextView(activity).apply {\n                text = ""\n                background = rounded(\n                    Color.parseColor(hex),\n                    0xFFE6EDF2.toInt(),\n                    8\n                )\n            }\n            row.addView(\n                swatch,\n                fixed(dp(23), dp(23))\n            )\n\n            val valueLabel =\n                label(\n                    "%02d %s • %d%%\\n%s".format(\n                        number,\n                        name,\n                        value,\n                        example\n                    ),\n                    6.8f,\n                    0xFFF1F3F8.toInt(),\n                    true\n                ).apply {\n                    setPadding(\n                        dp(6),\n                        0,\n                        dp(3),\n                        0\n                    )\n                    maxLines = 2\n                }\n\n            row.addView(\n                valueLabel,\n                LinearLayout.LayoutParams(\n                    dp(138),\n                    ViewGroup.LayoutParams.WRAP_CONTENT\n                )\n            )\n\n            val seek = SeekBar(activity).apply {\n                max = 200\n                progress = value\n                progressTintList =\n                    ColorStateList.valueOf(\n                        Color.parseColor(hex)\n                    )\n                thumbTintList =\n                    ColorStateList.valueOf(\n                        Color.parseColor(hex)\n                    )\n\n                setOnSeekBarChangeListener(\n                    object : SeekBar.OnSeekBarChangeListener {\n                        override fun onProgressChanged(\n                            seekBar: SeekBar?,\n                            progress: Int,\n                            fromUser: Boolean\n                        ) {\n                            valueLabel.text =\n                                "%02d %s • %d%%\\n%s".format(\n                                    number,\n                                    name,\n                                    progress,\n                                    example\n                                )\n\n                            if (fromUser && !loading) {\n                                save(progress)\n                                applyNow()\n                                updateHeader()\n                            }\n                        }\n\n                        override fun onStartTrackingTouch(\n                            seekBar: SeekBar?\n                        ) { }\n\n                        override fun onStopTrackingTouch(\n                            seekBar: SeekBar?\n                        ) { }\n                    }\n                )\n            }\n\n            row.addView(\n                seek,\n                LinearLayout.LayoutParams(\n                    0,\n                    dp(35),\n                    1f\n                )\n            )\n\n            return row\n        }\n\n        private fun applyNow() {\n            if (bypass) {\n                return\n            }\n\n            DevelopUgandaColorEngine.setMonitorEnabled(\n                activity,\n                true\n            )\n\n            DevelopUgandaColorEngine.applyPreviewMonitor(\n                previewView,\n                resolve(),\n                scope()\n            )\n        }\n\n        private fun resolve():\n            DevelopUgandaColorEngine.ResolvedSelection =\n            DevelopUgandaColorEngine.resolve(\n                activity,\n                scope(),\n                hint()\n            )\n\n        private fun refreshIfNeeded() {\n            val value = signature()\n\n            if (value != lastSignature) {\n                refreshUi(force = true)\n                applyNow()\n            }\n        }\n\n        private fun refreshUi(\n            force: Boolean\n        ) {\n            if (!force && signature() == lastSignature) {\n                return\n            }\n\n            loading = true\n\n            val selection = resolve()\n\n            masterSeek.progress =\n                selection.strength.coerceIn(0, 100)\n\n            masterLabel.text =\n                "MASTER LUT STRENGTH • ${selection.strength}%"\n\n            rebuildControls(selection)\n            updateHeader()\n\n            loading = false\n            lastSignature = signature()\n        }\n\n        private fun updateHeader() {\n            val selection = resolve()\n\n            val name =\n                selection.profile?.let {\n                    DevelopUgandaColorTuner.displayName(\n                        it.id,\n                        it.label\n                    )\n                } ?: "ORIGINAL"\n\n            val custom =\n                selection.profile?.let { profile ->\n                    val sceneCustom =\n                        !DevelopUgandaColorTuner\n                            .load(\n                                activity,\n                                scope(),\n                                profile.id\n                            )\n                            .isDefault()\n\n                    val everydayCustom =\n                        !DevelopUgandaEverydayColorMixer\n                            .load(\n                                activity,\n                                scope(),\n                                profile.id\n                            )\n                            .isDefault()\n\n                    when {\n                        sceneCustom && everydayCustom ->\n                            "SCENE + COLOR CUSTOM"\n                        everydayCustom ->\n                            "COLOR CUSTOM"\n                        sceneCustom ->\n                            "SCENE CUSTOM"\n                        else ->\n                            "BASE LUT"\n                    }\n                } ?: "RAW"\n\n            active.text =\n                "● V235 LIVE GRADE • $name\\n${selection.strength}% • $custom • HOLD ORIGINAL TO COMPARE"\n\n            chip.text =\n                "GRADE • ${selection.strength}%\\n${name.take(12)} ▸"\n\n            lookButton.text =\n                "LOOK ▾\\n${name.take(16)}"\n        }\n\n        private fun signature(): String {\n            val selection = resolve()\n            val profile = selection.profile\n\n            val scene =\n                if (profile == null) {\n                    "RAW"\n                } else {\n                    DevelopUgandaColorTuner\n                        .load(\n                            activity,\n                            scope(),\n                            profile.id\n                        )\n                        .values\n                        .joinToString(",")\n                }\n\n            val everyday =\n                if (profile == null) {\n                    "RAW"\n                } else {\n                    DevelopUgandaEverydayColorMixer\n                        .load(\n                            activity,\n                            scope(),\n                            profile.id\n                        )\n                        .values\n                        .joinToString(",")\n                }\n\n            return "${scope()}:${selection.requestedId}:${profile?.id}:${selection.strength}:$scene:$everyday"\n        }\n\n        private fun scope(): String =\n            scopeProvider().ifBlank {\n                "GLOBAL"\n            }\n\n        private fun hint(): String =\n            try {\n                hintProvider()\n            } catch (_: Exception) {\n                "REPORTER"\n            }\n\n        private fun smallButton(\n            textValue: String,\n            stroke: Int\n        ): Button =\n            Button(activity).apply {\n                text = textValue\n                textSize = 7.1f\n                isAllCaps = false\n                typeface = Typeface.DEFAULT_BOLD\n                setTextColor(Color.WHITE)\n                background =\n                    rounded(\n                        0xFF092236.toInt(),\n                        stroke,\n                        12\n                    )\n                setPadding(\n                    dp(3),\n                    0,\n                    dp(3),\n                    0\n                )\n            }\n\n        private fun sectionTitle(\n            value: String\n        ): TextView =\n            label(\n                value,\n                7.5f,\n                0xFFD0B06F.toInt(),\n                true\n            ).apply {\n                setPadding(\n                    0,\n                    dp(2),\n                    0,\n                    dp(2)\n                )\n            }\n\n        private fun label(\n            value: String,\n            size: Float,\n            color: Int,\n            bold: Boolean\n        ): TextView =\n            TextView(activity).apply {\n                text = value\n                textSize = size\n                setTextColor(color)\n                if (bold) {\n                    typeface = Typeface.DEFAULT_BOLD\n                }\n            }\n\n        private fun rounded(\n            fill: Int,\n            stroke: Int,\n            radius: Int\n        ): GradientDrawable =\n            GradientDrawable().apply {\n                shape = GradientDrawable.RECTANGLE\n                setColor(fill)\n                cornerRadius = dp(radius).toFloat()\n                setStroke(dp(1), stroke)\n            }\n\n        private fun space(\n            width: Int\n        ): View =\n            View(activity).apply {\n                layoutParams =\n                    LinearLayout.LayoutParams(\n                        width,\n                        1\n                    )\n            }\n\n        private fun weight():\n            LinearLayout.LayoutParams =\n            LinearLayout.LayoutParams(\n                0,\n                dp(42),\n                1f\n            )\n\n        private fun fixed(\n            width: Int,\n            height: Int\n        ): LinearLayout.LayoutParams =\n            LinearLayout.LayoutParams(\n                width,\n                height\n            )\n\n        private fun dp(\n            value: Int\n        ): Int =\n            (\n                value *\n                    activity.resources.displayMetrics.density\n                ).toInt()\n    }\n}\n'

